-- Shared auction fixtures: signed claims only, no real accounts or money.
begin;
create temporary table th_auction_results(stage text,result text) on commit drop;
create function pg_temp.th_auction_claim(uid uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','aal','aal1')::text,true);end$$;
create function pg_temp.th_auction_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'AUCTION ASSERT FAILED: %',label;end if;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values('97000000-7a21-4000-8000-000000000001','auction-one@example.invalid',now(),'{}'),('97000000-7a21-4000-8000-000000000002','auction-two@example.invalid',now(),'{}');
do $$declare one_user uuid:='97000000-7a21-4000-8000-000000000001';two_user uuid:='97000000-7a21-4000-8000-000000000002';state jsonb;p jsonb;reply jsonb;rid uuid;next_rid uuid;empty_rid uuid;oid uuid;receipt text;order_count integer;real_shop uuid;real_pid uuid;real_oid uuid;real_photo text;begin
 perform pg_temp.th_auction_claim(one_user);perform public.th_api('snapshot');perform pg_temp.th_auction_claim(two_user);perform public.th_api('snapshot');
 perform set_config('request.jwt.claims','{}',true);state:=public.th_api('snapshot');select v into p from jsonb_array_elements(state->'products')x(v) where v->>'id'='p14';rid:=(p->>'roundId')::uuid;
 perform pg_temp.th_auction_assert(state->'sampleAuctions'='true'::jsonb and p->'bidableDemo'='true'::jsonb and rid is not null and (p->>'price')::int=4900,'auction capability and starting price');
 begin perform public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',5000,'requestKey','sample-auction-anon-bid'));raise exception 'Anonymous bid accepted';exception when sqlstate 'PT401' then null;end;
 perform pg_temp.th_auction_claim(one_user);update auth.users set email_confirmed_at=null where id=one_user;
 begin perform public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',5000,'requestKey','sample-auction-unverified'));raise exception 'Unconfirmed bid accepted';exception when sqlstate 'PT403' then null;end;
 update auth.users set email_confirmed_at=now() where id=one_user;
 begin perform public.th_api('bid',jsonb_build_object('productId','p14','amount',5000,'requestKey','sample-auction-no-round'));raise exception 'Missing round accepted';exception when sqlstate 'PT400' then null;end;
 begin perform public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',4950,'requestKey','sample-auction-low-bid'));raise exception 'Below step bid accepted';exception when sqlstate 'PT409' then null;end;
 state:=public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',5000,'requestKey','sample-auction-one-bid'));perform pg_temp.th_auction_assert(state#>>'{bids,p14,status}'='leading','first buyer leads');
 perform public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',5000,'requestKey','sample-auction-one-bid'));perform pg_temp.th_auction_assert((select count(*)=1 from public.th_sample_bids where round_id=rid),'retries never duplicate bid');
 begin perform public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',5100,'requestKey','sample-auction-one-bid'));raise exception 'Changed bid key accepted';exception when sqlstate 'PT409' then null;end;
 perform pg_temp.th_auction_claim(two_user);
 begin perform public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',5000,'requestKey','sample-auction-two-low'));raise exception 'Equal competitor accepted';exception when sqlstate 'PT409' then null;end;
 state:=public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',5100,'requestKey','sample-auction-two-bid'));perform pg_temp.th_auction_assert(state#>>'{bids,p14,status}'='leading','second buyer leads');
 perform pg_temp.th_auction_claim(one_user);state:=public.th_api('snapshot');perform pg_temp.th_auction_assert(state#>>'{bids,p14,status}'='outbid' and jsonb_array_length(state#>'{bids,p14,history}')=1,'first buyer outbid with own history only');
 perform pg_temp.th_auction_assert(not exists(select 1 from public.th_sample_orders where payload->>'roundId'=rid::text),'winner order never created early');
 insert into pg_temp.th_auction_results values('Confirmed accounts compete with server bid step, private history and idempotent retries','PASS');
 update public.th_sample_rounds set starts_at=public.th_now()-180000,ends_at=public.th_now()-1 where id=rid;
 perform public.th_settle();perform public.th_settle();select order_id into oid from public.th_sample_rounds where id=rid;
 perform pg_temp.th_auction_assert((select status='closed' and winner_id=two_user and winning_amount=5100 and order_id is not null from public.th_sample_rounds where id=rid),'highest bidder wins on deadline');
 perform pg_temp.th_auction_assert((select count(*)=1 from public.th_sample_orders where payload->>'roundId'=rid::text) and (select total=5100 and user_id=two_user from public.th_sample_orders where id=oid),'exactly one winner order at server price');
 state:=public.th_api('snapshot');select v into p from jsonb_array_elements(state->'products')x(v) where v->>'id'='p14';next_rid:=(p->>'roundId')::uuid;
 perform pg_temp.th_auction_assert(next_rid<>rid and p#>'{lastAuctionResult,winnerIsYou}'='false'::jsonb and not(p->'lastAuctionResult'?'orderId') and state#>>'{bids,p14,status}'='lost','loser sees result without private winner order');
 perform pg_temp.th_auction_assert(not exists(select 1 from jsonb_array_elements(state->'orders')x(v) where v->>'id'=oid::text),'loser cannot see winner order');
 begin perform public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',5200,'requestKey','sample-auction-stale-bid'));raise exception 'Closed round accepted new bid';exception when sqlstate 'PT409' then null;end;
 perform public.th_api('bid',jsonb_build_object('productId','p14','roundId',rid,'amount',5000,'requestKey','sample-auction-one-bid'));
 perform pg_temp.th_auction_claim(two_user);state:=public.th_api('snapshot');select v into p from jsonb_array_elements(state->'products')x(v) where v->>'id'='p14';
 perform pg_temp.th_auction_assert(p#>>'{lastAuctionResult,orderId}'=oid::text and state#>>'{bids,p14,status}'='won','winner receives own order');
 reply:=public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','sample-auction-winner-pay'));receipt:=reply#>>'{payment,reference}';perform pg_temp.th_auction_assert(reply#>>'{payment,status}'='paid_demo' and (reply#>>'{payment,amount}')::int=5100,'winner pays simulated amount through main checkout');
 perform public.th_api('sample_complete',jsonb_build_object('orderId',oid));perform pg_temp.th_auction_assert((select status='completed' from public.th_sample_orders where id=oid),'winner completes sample pickup');
 perform set_config('request.jwt.claims','{}',true);state:=public.th_api('snapshot');select v into p from jsonb_array_elements(state->'products')x(v) where v->>'id'='p14';
 perform pg_temp.th_auction_assert(not(p->'lastAuctionResult'?'orderId') and position(receipt in state::text)=0 and position(one_user::text in state::text)=0 and position(two_user::text in state::text)=0,'public winner metadata has no identity, private order or receipt');
 insert into pg_temp.th_auction_results values('Deadline settlement creates one private winner order, refreshed round and payable checkout','PASS');
 select count(*) into order_count from public.th_sample_orders;select id into empty_rid from public.th_sample_rounds where product_id='p16' and status='active';
 update public.th_sample_rounds set starts_at=public.th_now()-180000,ends_at=public.th_now()-1 where id=empty_rid;perform public.th_settle();perform public.th_settle();
 perform pg_temp.th_auction_assert((select status='closed' and winner_id is null and order_id is null from public.th_sample_rounds where id=empty_rid) and (select count(*)=order_count from public.th_sample_orders),'empty auction closes without phantom buyer');
 perform pg_temp.th_auction_assert((select count(*)=6 from public.th_sample_rounds where status='active'),'one new active round per sample auction');
 perform pg_temp.th_auction_claim(one_user);
 begin perform public.th_api('reserve',jsonb_build_object('productIds',jsonb_build_array('p15'),'delivery','pickup','requestKey','sample-auction-'||next_rid));raise exception 'System auction request key stolen';exception when sqlstate 'PT400' then null;end;
 state:=public.th_api('bid',jsonb_build_object('productId','p14','roundId',next_rid,'amount',5000,'requestKey','sample-auction-next-bid'));perform pg_temp.th_auction_assert(state#>>'{bids,p14,status}'='leading','new round can be used after previous finished');
 insert into pg_temp.th_auction_results values('Empty rounds refresh without fake winners and stale round protection','PASS');
 -- Actual seller auctions retain their normal order and simulated payment path.
 perform pg_temp.th_auction_claim(one_user);select id into real_shop from public.th_shops where user_id=one_user;update public.th_shops set status='verified' where id=real_shop;
 real_photo:=one_user::text||'/97000000-7a21-4000-8000-000000000099.png';insert into storage.objects(bucket_id,name,owner_id,metadata) values('product-photos',real_photo,one_user::text,'{"mimetype":"image/png","size":1024}');perform public.th_api('upload_register',jsonb_build_object('path',real_photo));
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode,bid_step,ends_at) values(real_shop,'Actual auction fixture','Actual auction regression fixture','home','สภาพดี','Bangkok',real_photo,1000,'auction',100,public.th_now()+3600000) returning id into real_pid;
 perform pg_temp.th_auction_claim(two_user);state:=public.th_api('bid',jsonb_build_object('productId',real_pid,'amount',1100,'requestKey','actual-auction-regression-bid'));
 perform pg_temp.th_auction_assert(state#>>array['bids',real_pid::text,'status']='leading','actual auction bidder status');
 update public.th_products set ends_at=public.th_now()-1 where id=real_pid;perform public.th_settle();state:=public.th_api('snapshot');
 select id into real_oid from public.th_orders where user_id=two_user and request_key='auction-'||real_pid;
 perform pg_temp.th_auction_assert(real_oid is not null and (select payment_required from public.th_orders where id=real_oid) and state#>>array['bids',real_pid::text,'status']='won' and state#>>array['bids',real_pid::text,'orderId']=real_oid::text,'actual winner receives payment-required order');
 reply:=public.th_api('pay',jsonb_build_object('orderId',real_oid,'method','card_demo','outcome','success','requestKey','actual-auction-regression-pay'));
 perform pg_temp.th_auction_assert(reply#>>'{payment,status}'='paid_demo' and (reply#>>'{payment,amount}')::int=1100,'actual auction winner pays server winning amount');
 insert into pg_temp.th_auction_results values('Actual seller auction winner status, payment-required order and simulated checkout regression','PASS');

end$$;
set local role authenticated;
do $$begin
 begin perform 1 from public.th_sample_rounds;raise exception 'Direct rounds readable';exception when insufficient_privilege then null;end;
 begin perform 1 from public.th_sample_bids;raise exception 'Direct bids readable';exception when insufficient_privilege then null;end;
 begin perform public.th_settle_v5_base();raise exception 'Previous settlement helper exposed';exception when insufficient_privilege then null;end;
 begin perform public.th_api_v5_base('snapshot');raise exception 'Previous dispatcher exposed';exception when insufficient_privilege then null;end;
end$$;
reset role;
select stage,result from pg_temp.th_auction_results;
rollback;
